fn exec_turns_to_defeat(health: i8, strength: i8) -> i64 {
    let h = health as i64;
    let s = strength as i64;
    // Ceil division for positive integers: (h + s - 1) / s
    (h + s - 1) / s
}

fn solve(a: i8, b: i8, c: i8, d: i8) -> String {
    let takahashi_turns = exec_turns_to_defeat(c, b); // turns for Takahashi to defeat Aoki
    let aoki_turns = exec_turns_to_defeat(a, d);      // turns for Aoki to defeat Takahashi

    if takahashi_turns <= aoki_turns {
        "Yes".to_string()
    } else {
        "No".to_string()
    }
}

